    if (trigger_track >= NUM_TRACKS)
        return;
    slot = (trigger_track >= INSTRUMENT_SLOT_COUNT)
        ? (INSTRUMENT_SLOT_COUNT - 1u) : trigger_track;
    /* S081 P2: this track's ramps end at its own next step first. */
    seq_rampConsumeTrack(trigger_track);
